frame.store("_where_the_rest_is", { let __default_2319 = Value::from(""); let __signature_2317 = Signature { name: "_where_the_rest_is".into(), positional: vec!["said".into(),"memory".into(),"turn".into(),"ask".into()], positional_only: 0, defaults: vec![__default_2319], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_2320 = Value::dict(); __attrs_2320.dict_set(Value::from("__doc__"), Value::from("The one place that settles what an answer in hand does not cover, read off the answer.\n\n    Where the rest of it lives is read off the card's own line, not the ask: \"should i keep\n    driving\" carries no subject, and the subject of the chat is what the answer was about. The\n    card's own words, and the entries it came from, go in too: a timings card for a roast says\n    \"20 minutes per 500g ... a 2kg bird\" and names no oven at all, while the entry behind it is\n    keyed on one. Without them the place came from the topic of the turn that asked for the\n    figure - \"how long does it take anyway\" reads as maths, and the reply offered \"a calculator\"\n    for whether to cover a chicken with foil.\n    "))?; __attrs_2320.dict_set(Value::from("__defaults__"), Value::tuple(__signature_2317.defaults.clone()))?; let __kwdefaults_2321 = Value::dict(); __attrs_2320.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_2316 = Frame::module(frame.globals.clone()); let mut __function_2318 = NativeFunction::qualified_with_attrs("_where_the_rest_is".into(), "_where_the_rest_is".into(), "bot.memory.repeat".into(), __attrs_2320, move |rt, args| __py_127::_where_the_rest_is(rt, __closure_2316.clone(), &__signature_2317, args)); __function_2318 })?;
